contract InvMutTest {
    C c;
    bool rejectPayments;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        uint beforeC = address(c).balance;
        uint beforeT = address(this).balance;

        c.deposit{value: amount}();

        rejectPayments = true;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        rejectPayments = false;
        c.withdrawAll();

        assert(
            reverted
            && address(c).balance == beforeC
            && address(this).balance == beforeT
        );
    }

    receive() external payable {
        require(!rejectPayments);
    }
}

